using System;
using System.Linq;
using MET.Core;
// Focused settlement fixture. Freight and stock are explicitly staged so this
// checks exact settlement/purchase invariants, not early-game freight pacing.
class WildContentProgram {
 static int checks;
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 static void Near(double actual,double expected,string label)=>Check(Math.Abs(actual-expected)<1e-6*Math.Max(1,Math.Abs(expected)),label+" ("+actual+" / "+expected+")");
 static void Command(string error,string label)=>Check(error=="",label+(error==""?"":": "+error));
 static string Cell(Game g)=>Rules.ids(g.s["cells"]).First(x=>!g.s["cells"][x]["traits"].Contains("tile.water")&&g.s["cells"][x]["building"].Text=="").Text;
 static void Origin(CitySession city){var old=city.FocusedGame.snapshot();Command(city.FocusedGame.choose_origin(city.FocusedGame.s["origin_choices"][0].Text),"choose existing origin");city.AfterLocalCommand(old);}
 static void Settle(CitySession city,double seconds){city.SettleNetwork(seconds);city.s["external_seconds"]+=seconds;}
 static V LastOrder(Game g)=>g.s["block"]["trade_orders"][-1];
 static CitySession Reload(Catalog c,CitySession city,string label){var r=new CitySession(c);Command(r.Restore(city.snapshot()),label);return r;}
 static void Milestones(Catalog c,CitySession completed) {
  var original=c.wild["milestones"].Duplicate(true);
  var state=completed.snapshot();var legacy=state.Duplicate(true);legacy["wild_technology"]["reward"]=completed.WildRewardView();legacy["wild_technology"].Remove("rewards");
  var migrated=new CitySession(c);Command(migrated.Restore(legacy),"legacy single reward migrates");Check(!migrated.s["wild_technology"].Has("reward"),"legacy field retired");Check(migrated.WildRewardView()==completed.WildRewardView(),"legacy exact offer preserved");
  var before=migrated.snapshot().ToJson(sortKeys:true);var view=CitySession.WildRewardsView(c,migrated.s,migrated.FocusedBlockId,true);view[0]["choices"][0]["amount"]=99;migrated.WildRewardView()["choices"][0]["amount"]=99;Check(migrated.snapshot().ToJson(sortKeys:true)==before,"both views detached read only");
  var extra=original[0].Duplicate(true);extra["id"]="test:second";extra["name"]="fixture second";extra["choices"][0]["amount"]=3;c.wild["milestones"].Add(extra);
  Command(migrated.EnsureWildReward(),"multiple configured milestones generate");Near(migrated.s["wild_technology"]["rewards"].Count,2,"two distinct persisted offers");var once=migrated.snapshot().ToJson(sortKeys:true);Command(migrated.EnsureWildReward(),"repeat generation");Check(once==migrated.snapshot().ToJson(sortKeys:true),"generation idempotent");
  c.wild["milestones"]=V.Arr();var stable=Reload(c,migrated,"removed config preserves offers");Check(stable.snapshot().ToJson(sortKeys:true)==once,"removed config no reroll on load");stable.FocusedGame.s["projects"]["municipal"]["inventory"]["material"]=0;Command(stable.ClaimWildReward("test:second","material"),"claim removed definition saved amount");Near(stable.FocusedGame.s["projects"]["municipal"]["inventory"]["material"].Double,3,"saved amount authoritative");stable=Reload(c,stable,"claimed removed config reload");before=stable.snapshot().ToJson(sortKeys:true);Check(stable.ClaimWildReward("test:second","material")!="","duplicate milestone claim rejected");Check(before==stable.snapshot().ToJson(sortKeys:true),"duplicate all state unchanged");
  c.wild["milestones"]=original.Duplicate(true);c.wild["milestones"][0]["choices"][0]["amount"]=77;stable=Reload(c,stable,"changed config pending reload");Near(stable.WildRewardView()["choices"][0]["amount"].Double,10,"pending offer not rerolled");
  foreach(var bad in new[]{V.Map("kind","unknown"),V.Map("amount",-1),V.Map("amount",0),V.Map("amount","10"),V.Map("amount",double.NaN),V.Map("amount",double.PositiveInfinity),V.Map("resource","bogus"),V.Map("id",""),V.Map("name","")}) {
   c.wild["milestones"]=original.Duplicate(true);foreach(var field in bad.Pairs)c.wild["milestones"][0]["choices"][0][field.Key]=field.Value;
   before=stable.snapshot().ToJson(sortKeys:true);Check(stable.EnsureWildReward()!="","bad configured choice refused "+bad.Keys[0]);Check(before==stable.snapshot().ToJson(sortKeys:true),"bad config generation pure");
  }
  c.wild["milestones"]=original.Duplicate(true);c.wild["milestones"].Add(original[0].Duplicate(true));Check(CitySession.ValidateWildMilestones(c)!="","duplicate milestones rejected");c.wild["milestones"]=original.Duplicate(true);c.wild["milestones"][0]["choices"].Add(original[0]["choices"][0].Duplicate(true));Check(CitySession.ValidateWildMilestones(c)!="","duplicate options rejected");
  c.wild["milestones"]=original.Duplicate(true);c.wild["milestones"][0]["choices"][2]["amount"]=2;Check(CitySession.ValidateWildMilestones(c)!="","bonus multiple amount rejected");
  c.wild["milestones"]=original.Duplicate(true);c.wild["milestones"][0]["choices"][2]["bonus_id"]="unknown";Check(CitySession.ValidateWildMilestones(c)!="","unknown bonus rejected");
  c.wild["milestones"]=original.Duplicate(true);c.wild["milestones"][0]["id"]=" spaced ";Check(CitySession.ValidateWildMilestones(c)!="","noncanonical reward id rejected");
  c.wild["milestones"]=original;
  var legacyClaimed=legacy.Duplicate(true);legacyClaimed["wild_technology"]["reward"]["claimed"]=true;legacyClaimed["wild_technology"]["reward"]["chosen"]="material";var prior=new CitySession(c);Command(prior.Restore(legacyClaimed),"claimed legacy migration");before=prior.snapshot().ToJson(sortKeys:true);Command(prior.EnsureWildReward(),"claimed legacy ensure");Check(prior.ClaimWildReward("material")!="","claimed legacy cannot claim again");Check(prior.snapshot().ToJson(sortKeys:true)==before,"claimed legacy no reroll");Check(!CitySession.WildRewardsView(c,completed.s,completed.FocusedBlockId,true,false)[0]["can_claim"].Bool,"nonplay view disables claim");
  foreach(var field in new[]{"kind","resource","id","amount"}) {var broken=state.Duplicate(true);broken["wild_technology"]["rewards"]["wild:hope-design-ii:v1"]["choices"][0][field]=field=="id"?"":"invalid";var target=new CitySession(c);Check(target.Restore(broken)!="","malformed saved choice rejected "+field);}
  var wrong=Reload(c,completed,"source ownership fixture");string other=wrong.s["blocks"].Keys.First(x=>x!=wrong.FocusedBlockId);Command(wrong.FocusBlock(other),"focus other source");before=wrong.snapshot().ToJson(sortKeys:true);Check(wrong.ClaimWildReward("material")!="","wrong source cannot claim");Check(before==wrong.snapshot().ToJson(sortKeys:true),"wrong source command pure");Check(!CitySession.WildRewardsView(c,wrong.s,other,true)[0]["can_claim"].Bool,"wrong source view disables claim");
 }
 static void Main(string[] args){
  var c=new Catalog(args[0]);var city=new CitySession(c);Command(city.BeginDistrict(0,"balanced"),"start original district");Origin(city);var g=city.FocusedGame;
  var unenabled=city.snapshot().ToJson(sortKeys:true);Check(!city.WildView()["enabled"].Bool,"old city remains outside Wild until explicit enable");city.WildView();Check(city.snapshot().ToJson(sortKeys:true)==unenabled,"disabled Wild view is read only");
  Command(city.EnableWild(),"explicitly enable focused Wild block");var beforeEnable=city.snapshot().ToJson(sortKeys:true);Command(city.EnableWild(),"repeat enable succeeds");Check(city.snapshot().ToJson(sortKeys:true)==beforeEnable,"repeat enable does not duplicate stock or history");
  Check(Market.order(g,"material","sell",10,0,CitySession.WildHopeCounterparty)!="","starter cannot bypass existing freight requirement");
  var freight=g.create_building("freight",Cell(g),"civic",true);freight["usage"]=1;g.refresh_metrics();freight["usage"]=1;
  string existingFarm=g.create_building("homestead",Cell(g),"civic",true)["id"].Text;g.refresh_metrics();double existingCapacity=WildDesign.View(g,existingFarm)["capacity"]["total"].Double;
  g.s["projects"]["municipal"]["inventory"]["material"]=100;g.s["projects"]["municipal"]["inventory"]["goods"]=20;g.s["currency"]=200;city.ApplyWorldEffects();
  Check(city.BuyWildHousing()!="","purchase blocked before actual exports");
  var oldZero=Reload(c,city,"legacy level0 reload without II or reward fields");Near(oldZero.WildView()["housing_levels"].Long,0,"legacy zero stays zero");Check(oldZero.WildRewardView().Count==0,"legacy zero gets no task reward");Check(city.BuyWildHousingII()!="","II requires I");
  Command(Market.order(g,"material","sell",10,100000,CitySession.WildHopeCounterparty),"open noncrossing Hope order");var cancelled=LastOrder(g);Settle(city,3600);Near(city.WildView()["material_exported"].Double,0,"unfilled order does not grant eligibility");Command(Market.cancel(g,cancelled["id"].Text),"cancel unfilled order");Settle(city,3600);Near(city.WildView()["material_exported"].Double,0,"cancelled order does not grant eligibility");
  Command(Market.order(g,"material","sell",2,0),"ordinary market export");Settle(city,3600);Near(LastOrder(g)["filled"].Double,2,"ordinary market export actually fills");Near(city.WildView()["material_exported"].Double,0,"untagged market exports do not count for Hope");
  Command(Market.order(g,"material","sell",2,0,"other"),"other counterparty material export");Settle(city,3600);Near(LastOrder(g)["filled"].Double,2,"other counterparty export actually fills");Near(city.WildView()["material_exported"].Double,0,"other counterparty does not count for Hope");
  Command(Market.order(g,"goods","sell",1,0,CitySession.WildHopeCounterparty),"Hope goods export");Settle(city,3600);Near(LastOrder(g)["filled"].Double,1,"Hope goods export actually fills");Near(city.WildView()["material_exported"].Double,0,"other resource exports do not count");
  Command(Market.order(g,"material","buy",1,100,CitySession.WildHopeCounterparty),"Hope material import");Settle(city,3600);Near(LastOrder(g)["filled"].Double,1,"Hope import actually fills");Near(city.WildView()["material_exported"].Double,0,"imports do not count");
  double stock=g.inventory_total("material");Command(Market.order(g,"material","sell",10,0,CitySession.WildHopeCounterparty),"real Hope material sell");string order=LastOrder(g)["id"].Text;double cap=Math.Min(Market._total_capacity(g),city.s["world_market"]["capacity_per_hour"].Double);Settle(city,3600/cap*3);
  Near(city.WildView()["material_exported"].Double,3,"partial fill counts only actual shipped quantity");Near(stock-g.inventory_total("material"),3,"partial fill withdraws material once");Check(!city.WildView()["can_purchase"].Bool,"partial fill below requirement stays locked");
  Check(g.s["block"]["trade_history"][-1]["counterparty"].Text==CitySession.WildHopeCounterparty,"actual history identifies Hope counterparty");Check(city.s["network"]["last_tick"]["outside_trades"][-1]["counterparty"].Text==CitySession.WildHopeCounterparty,"real-time network receipt identifies Hope counterparty");
  var restored=new CitySession(c);Command(restored.Restore(city.snapshot()),"restore partial export city");city=restored;g=city.FocusedGame;cap=Math.Min(Market._total_capacity(g),city.s["world_market"]["capacity_per_hour"].Double);Settle(city,3600/cap*7);Near(city.WildView()["material_exported"].Double,10,"post-restore fill accumulates exact remaining exports");Near(city.WildView()["eligibility_history"].Count,1,"threshold produces one retained eligibility record");
  var readonlyState=city.snapshot().ToJson(sortKeys:true);city.WildView();city.WildView();Check(city.snapshot().ToJson(sortKeys:true)==readonlyState,"eligible Wild view does not mutate live state");
  g.s["currency"]=59;Check(city.BuyWildHousing()!="","eligible purchase still requires actual currency");g.s["currency"]=200;double paidStock=g.inventory_total("material");Command(city.BuyWildHousing(),"buy HousingDesignI with 60 actual currency");Near(g.s["currency"].Double,140,"purchase charges exactly 60 currency");Near(g.inventory_total("material"),paidStock,"purchase does not re-deduct exported material");Near(city.s["wild_technology"]["housing_levels"].Long,1,"city owns one housing technology level");Near(g.world_effects["wild_housing_levels"].Long,1,"existing block receives city technology projection");
  var purchased=city.snapshot().ToJson(sortKeys:true);Check(city.BuyWildHousing()!="","duplicate purchase refused");Check(city.snapshot().ToJson(sortKeys:true)==purchased,"duplicate purchase changes no wallet or history");city.ApplyWorldEffects();city.ApplyWorldEffects();Near(g.world_effects["wild_housing_levels"].Long,1,"repeated projection does not stack technology levels");
  Near(WildDesign.View(g,existingFarm)["capacity"]["total"].Double,existingCapacity+2,"existing building receives exactly two city DP");
  var future=g.create_building("homestead",Cell(g),"civic",true);g.refresh_metrics();Near(WildDesign.View(g,future["id"].Text)["capacity"]["technology"].Double,2,"future building derives two DP from city technology");
  string first=city.FocusedBlockId;g.s["currency"]=3000;foreach(string r in new[]{"food","material","goods"})g.s["projects"]["municipal"]["inventory"][r]=80;Command(city.BeginBlock(1,"balanced",first),"future block pays normal startup");Origin(city);Command(city.EnableWild(),"explicitly enable future Wild block");Near(city.FocusedGame.world_effects["wild_housing_levels"].Long,1,"future block inherits city projection");var later=city.FocusedGame.create_building("homestead",Cell(city.FocusedGame),"civic",true);Near(WildDesign.View(city.FocusedGame,later["id"].Text)["capacity"]["technology"].Double,2,"future block building receives shared technology");
  var loaded=new CitySession(c);Command(loaded.Restore(city.snapshot()),"restore purchased city");Near(loaded.WildView()["housing_levels"].Long,1,"restore keeps purchased technology");Near(loaded.WildView()["material_exported"].Double,10,"restore keeps cumulative export eligibility");Check(loaded.Validate()=="","complete purchased city validates");
  city=loaded;Command(city.FocusBlock(first),"focus source");g=city.FocusedGame;
  foreach(var project in g.s["projects"].Values)if(project.Get("def","").Text=="freight")project["usage"]=1;
  Command(Market.order(g,"material","sell",10,0,CitySession.WildHopeCounterparty),"second real export order");// Settle only the required shipment window: a ten-hour jump replenishes the outside warehouse to full before trading.
  cap=Math.Min(Market._total_capacity(g),city.s["world_market"]["capacity_per_hour"].Double);Settle(city,3600/cap*10);
  Near(LastOrder(g)["filled"].Double,10,"second order actually ships ten material");
  Near(city.WildView()["material_exported"].Double,20,"II cumulative actual exports");g.s["currency"]=89;Check(city.BuyWildHousingII()!="","II insufficient currency");g.s["currency"]=200;
  var configBefore=c.wild["milestones"].Duplicate(true);c.wild["milestones"][0]["choices"][0]["amount"]=-1;var rejectedII=city.snapshot().ToJson(sortKeys:true);Check(city.BuyWildHousingII()!="","invalid config blocks II before spending");Check(city.snapshot().ToJson(sortKeys:true)==rejectedII,"bad II config all state unchanged");Check(!city.WildHousingIIView()["can_purchase"].Bool,"bad config II view agrees");c.wild["milestones"]=configBefore;
  var historical=Reload(c,city,"config threshold fixture");var iiConfig=c.wild["housing_design_ii"].Duplicate(true);historical.s["wild_technology"]["material_exported"]=15;c.wild["housing_design_ii"]["required_exports"]=15;c.wild["housing_design_ii"]["cost"]=45;Near(historical.WildHousingIIView()["cost"].Double,45,"II view configured price");Command(historical.BuyWildHousingII(),"configured II threshold purchase");c.wild["housing_design_ii"]["required_exports"]=100;historical=Reload(c,historical,"historical configured threshold survives catalog changes");Near(historical.s["wild_technology"]["purchase_ii"]["required_exports"].Double,15,"receipt retains historical threshold");c.wild["housing_design_ii"]=iiConfig;
  Command(city.BuyWildHousingII(),"buy II");Near(g.s["currency"].Double,110,"II charges90");Near(WildDesign.View(g,existingFarm)["capacity"]["total"].Double,6,"II capacity6");
  var boughtII=city.snapshot().ToJson(sortKeys:true);Check(city.BuyWildHousingII()!="","II no duplicate");Check(city.snapshot().ToJson(sortKeys:true)==boughtII,"duplicate II preserves wallet stock receipt reward");
  Milestones(c,city);
  var reward=city.WildRewardView().ToJson(sortKeys:true);var reload=Reload(c,city,"II restore");Check(reload.WildRewardView().ToJson(sortKeys:true)==reward,"stable offer");reload.ApplyWorldEffects();reload.ApplyWorldEffects();Near(WildDesign.View(reload.FocusedGame,existingFarm)["capacity"]["total"].Double,6,"reload repeated projection stays six DP");
  foreach(var resource in new[]{"material","goods"}) {
   var branch=Reload(c,city,"unclaimed resource branch "+resource);var bg=branch.FocusedGame;var inv=bg.s["projects"]["municipal"]["inventory"];double amount=resource=="material"?10:1;
   inv[resource]=bg.stock_cap_for("municipal",resource);var full=branch.snapshot().ToJson(sortKeys:true);Check(branch.ClaimWildReward(resource)!="","full storage refuses "+resource);Check(branch.snapshot().ToJson(sortKeys:true)==full,"failed reward preserves snapshot "+resource);
   inv[resource]=0;Command(branch.ClaimWildReward(resource),"claim "+resource);Near(inv[resource].Double,amount,"exact resource grant "+resource);var claimed=Reload(c,branch,"claimed resource reload "+resource);var unchanged=claimed.snapshot().ToJson(sortKeys:true);Check(claimed.ClaimWildReward(resource)!="","reload refuses resource duplicate "+resource);Check(claimed.snapshot().ToJson(sortKeys:true)==unchanged,"duplicate resource preserves state "+resource);
  }
  g=reload.FocusedGame;long charges=g.s["block"]["bonus_wallet"].Get("W01",V.Map()).Get("charges",0).Long;int instances=g.s["bonus_instances"].Count;
  Command(reload.ClaimWildReward("W01"),"claim bonus to inventory");Near(g.s["block"]["bonus_wallet"]["W01"]["charges"].Long,charges+1,"exact one W01 charge");Near(g.s["bonus_instances"].Count,instances,"claim does not auto install");
  reload=Reload(c,reload,"claimed W01 restore");g=reload.FocusedGame;var claimedBonus=reload.snapshot().ToJson(sortKeys:true);Check(reload.ClaimWildReward("W01")!="","reload refuses W01 duplicate");Check(reload.snapshot().ToJson(sortKeys:true)==claimedBonus,"duplicate W01 preserves all state");
  // Explicit construction throughput/resource fixture; use actual queue completion and install API.
  g.s["block"]["construction_capacity"]=1000;g.s["projects"]["municipal"]["inventory"]["material"]=1000;g.s["projects"]["municipal"]["inventory"]["goods"]=100;
  foreach(var node in new[]{"compound","housing","organization"}) {Command(WildDesign.Start(g,existingFarm,node),"start manual slot route "+node);for(int i=0;i<200&&g.s["projects"][existingFarm]["upgrade_job"].Count>0;i++)Command(Sim.tick(g,.1),"construction simulation "+node);Check(g.s["projects"][existingFarm]["upgrade_job"].Count==0,"queue completes "+node);}
  double baseFood=g.compiled["stats"][existingFarm]["output.food"].Double;Command(Bonus.install(g,"W01","building",existingFarm,"wild:organization"),"manually install W01 into completed Organization slot");g.refresh_metrics();Near(g.s["block"]["bonus_wallet"]["W01"]["charges"].Long,charges,"manual install consumes exactly one charge");Near(g.compiled["stats"][existingFarm]["output.food"].Double,baseFood*1.15,"installed W01 applies fifteen percent food");
  Check(Rules.condition(g.s,existingFarm,V.Map("wild_no_upgrade",true)),"idle condition");g.s["projects"][existingFarm]["upgrade_job"]=V.Map("work",1);g.refresh_metrics();Check(!Rules.condition(g.s,existingFarm,V.Map("wild_no_upgrade",true)),"unfinished upgrade disables");Near(g.compiled["stats"][existingFarm]["output.food"].Double,baseFood,"upgrade removes food bonus dynamically");g.s["projects"][existingFarm]["paused"]=true;Check(!Rules.condition(g.s,existingFarm,V.Map("wild_no_upgrade",true)),"paused unfinished upgrade still disables");g.s["projects"][existingFarm]["paused"]=false;g.s["projects"][existingFarm]["upgrade_job"]=V.Map();g.refresh_metrics();Near(g.compiled["stats"][existingFarm]["output.food"].Double,baseFood*1.15,"finished upgrade restores bonus");
  var fresh=new CitySession(c);fresh.s["wild_mode"]=true;Command(fresh.BeginDistrict(0,"balanced"),"dedicated Wild launcher begins normal district onboarding");Origin(fresh);Check(WildDesign.Enabled(fresh.FocusedGame)&&fresh.WildView()["enabled"].Bool,"dedicated Wild mode enables only after actual origin");var started=fresh.snapshot().ToJson(sortKeys:true);fresh.AfterLocalCommand(fresh.FocusedGame.snapshot());Check(fresh.snapshot().ToJson(sortKeys:true)==started,"later ordinary local commands do not duplicate Wild opening grant");
  Console.WriteLine("WILD CONTENT CHECKS "+checks+" passed");
 }
}
